                else:
                    v=a[j:]
                    if v.startswith('='):v=v[1:]
                    if j==len(a):
                        if i==len(argv):missing(k)
                        v=argv[i]
                        if v.startswith('-') and v!='-':
                            if (v.startswith('--') and v.split('=')[0][2:] in ORDER) or (len(v)>1 and v[1] in SHORT):missing(k)
