    if not set(seen)&GROUPS[1]:missing_groups.append(DEST)
    if missing_groups:
        fail('the following required arguments were not provided:\n'+'\n'.join('  '+s for s in missing_groups),usage(prog,seen,bool(files),required_files=True))
    opts['files']=files
    if opts.quiet:opts['verbose']=0
    return opts
