static float sinc(float x) {
    if(x==0.f)return 1.f;
    float p=x*float(3.14159265358979323846);
    return std::sin(p)/p;
}
static float kernel(float x,int filter) {
    x=std::abs(x);
    if(filter==0)return x<0.5f?1.f:0.f;
    if(filter==1)return x<1.f?1.f-x:0.f;
    if(filter==2) {
        if(x<1.f)return 1.5f*x*x*x-2.5f*x*x+1.f;
        if(x<2.f)return -.5f*x*x*x+2.5f*x*x-4.f*x+2.f;
        return 0.f;
    }
    if(filter==3)return std::exp(-2.f*x*x)/std::sqrt(float(3.14159265358979323846)/2.f);
    return x<3.f?sinc(x)*sinc(x/3.f):0.f;
}
struct Sample { int start;std::vector<float> weights; };
static std::vector<Sample> make_samples(int oldsize,int newsize,int filter) {
    std::vector<Sample> result(newsize);
    float ratio=float(oldsize)/float(newsize),sratio=std::max(1.f,ratio);
    float support=(filter==0?.0f:filter==1?1.f:filter==2?2.f:3.f)*sratio;
    for(int out=0;out<newsize;out++) {
        float center=(out+0.5f)*ratio;
        int left=std::max(0,std::min(oldsize-1,int(std::floor(center-support))));
        int right=std::min(oldsize,std::max(left+1,int(std::ceil(center+support))));
        auto& s=result[out];s.start=left;float sum=0;
        for(int in=left;in<right;in++) {float w=kernel((in-center+0.5f)/sratio,filter);s.weights.push_back(w);sum+=w;}
        for(float& w:s.weights)w/=sum;
    }
    return result;
}
extern "C" unsigned char* bridge_resize(const unsigned char* input,int w,int h,int nw,int nh,int channels,int filter) {
    if(w<=0||h<=0||nw<=0||nh<=0||(size_t)nw*nh>150000000)return nullptr;
    auto ys=make_samples(h,nh,filter);auto xs=make_samples(w,nw,filter);
    std::vector<float> temp((size_t)w*nh*channels);
    for(int y=0;y<nh;y++)for(int x=0;x<w;x++)for(int c=0;c<channels;c++) {
        float v=0;
        const auto& s=ys[y];
        for(size_t j=0;j<s.weights.size();j++)v+=input[((size_t)(s.start+j)*w+x)*channels+c]*s.weights[j];
        temp[((size_t)y*w+x)*channels+c]=v;
    }
    auto* output=(unsigned char*)malloc((size_t)nw*nh*channels);
    if(!output)return nullptr;
    for(int y=0;y<nh;y++)for(int x=0;x<nw;x++)for(int c=0;c<channels;c++) {
        float v=0;const auto& s=xs[x];
        for(size_t j=0;j<s.weights.size();j++)v+=temp[((size_t)y*w+s.start+j)*channels+c]*s.weights[j];
        output[((size_t)y*nw+x)*channels+c]=(unsigned char)std::max(0.f,std::min(255.f,std::round(v)));
    }
