extern "C" void bridge_sample_dct(const unsigned char* pixels,int w,int h,int n,const int* info,int ycc,short* out) {
    int maxh=1,maxv=1;
    for(int i=0;i<n;i++){maxh=std::max(maxh,info[68*i+2]);maxv=std::max(maxv,info[68*i+3]);}
    size_t offset=0;
    auto dct=fn<void(*)(short*)>("jpeg_fdct_islow");
    for(int comp=0;comp<n;comp++) {
        int bw=info[68*comp],bh=info[68*comp+1];
        int sx=maxh/info[68*comp+2],sy=maxv/info[68*comp+3];
        int pw=(w+sx-1)/sx,ph=(h+sy-1)/sy;
        for(int by=0;by<bh;by++)for(int bx=0;bx<bw;bx++) {
            short values[64];
            for(int y=0;y<8;y++)for(int x=0;x<8;x++) {
                int ix=std::min(pw-1,bx*8+x),iy=std::min(ph-1,by*8+y);
                int sum=0;
                for(int dy=0;dy<sy;dy++)for(int dx=0;dx<sx;dx++) {
                    const unsigned char* p=pixels+((size_t)std::min(h-1,iy*sy+dy)*w+std::min(w-1,ix*sx+dx))*4;
                    int v;
                    if(n==1 || ycc)v=p[comp];
                    else if(comp==0)v=(19595*p[0]+38470*p[1]+7471*p[2]+32768)>>16;
                    else if(comp==1)v=(-11059*p[0]-21709*p[1]+32768*p[2]+(128<<16)+32767)>>16;
                    else v=(32768*p[0]-27439*p[1]-5329*p[2]+(128<<16)+32767)>>16;
                    sum+=v;
