    size_t count=0;for(int i=0;i<n;i++)count+=(size_t)info[i*68]*info[i*68+1]*64;
    std::vector<short> precise(count);
    bridge_sample_dct(pixels,w,h,n,info,1,precise.data());
    int lengths[512];bridge_default_ac_lengths(lengths);
    static const int zig[64]={0,1,8,16,9,2,3,10,17,24,32,25,18,11,4,5,12,19,26,33,40,48,41,34,27,20,13,6,7,14,21,28,35,42,49,56,57,50,43,36,29,22,15,23,30,37,44,51,58,59,52,45,38,31,39,46,53,60,61,54,47,55,62,63};
    size_t offset=0;
    for(int comp=0;comp<n;comp++) {
        const int* table=lengths+(comp?256:0);const int* qt=info+comp*68+4;
        double lambda=qt[0]*double(qt[0])*(.1+.04*(100-quality));
        for(int block=0;block<info[comp*68]*info[comp*68+1];block++,offset+=64) {
            int nodes[64]={},total=1,pred[64]={};double delta[64]={},cost[64];bool forced_zero[64]={};
            std::fill(cost,cost+64,1e90);cost[0]=0;
            for(int k=1;k<64;k++) {
                int idx=zig[k],level=std::abs(int(coeffs[offset+idx]));
                if(!level)continue;
                nodes[total++]=k;double value=std::abs(double(precise[offset+idx]))/8.;
                delta[k]=level==1?2*qt[idx]*value-qt[idx]*double(qt[idx]):1e60;
                forced_zero[k]=level==1&&value<=qt[idx]*.625&&k!=63;
            }
            for(int i=1;i<total;i++) {
                int pos=nodes[i],level=std::abs(int(coeffs[offset+zig[pos]])),bits=0;
                for(int x=level;x;x>>=1)bits++;
                if(forced_zero[pos])continue;
                double penalty=0;
                for(int j=i-1;j>=0;j--) {
                    int run=pos-nodes[j]-1;
                    double rate=(run/16)*table[240]+table[(run%16)*16+bits]+bits;
                    double value=cost[j]+penalty+lambda*rate;
                    if(value<cost[i]){cost[i]=value;pred[i]=j;}
                    if(j)penalty+=delta[nodes[j]];
                    if(penalty>1e50)break;
                }
            }
            double best=1e90,penalty=0;int last=0;
            for(int i=total-1;i>=0;i--) {
                double value=cost[i]+penalty+(nodes[i]<63?lambda*table[0]:0);
                if(value<best){best=value;last=i;}
                if(i)penalty+=delta[nodes[i]];
                if(penalty>1e50)break;
            }
            bool keep[64]={};keep[0]=true;
            while(last){keep[nodes[last]]=true;last=pred[last];}
            for(int i=1;i<total;i++)if(!keep[nodes[i]])coeffs[offset+zig[nodes[i]]]=0;
        }
    }
    int ret=bridge_jpeg_lossless(data,len,baseline,0,output,output_len,error,nullptr,0,coeffs);
    free(coeffs);free(info);return ret;
}
